-- ============================================================
--  Rodex — DATOS DEMO: Autorepuestos (empresa 18)
--  Empresa 18 · usuario 17 · caja 15 · sucursal 14 · almacén 16
--  Carga 10 días pasados (relativos a la fecha en que se corre):
--  proveedores, clientes, 32 productos, 3 compras, ventas diarias
--  con su cobro en caja, gastos y cierres de caja. Hoy queda libre.
--  · SQL plano (sin procedimientos): sirve con usuarios sin permiso
--    CREATE/ALTER ROUTINE (hosting administrado).
--  · Antes de cargar valida empresa/caja/sucursal/almacén/usuario y
--    que no estén ya los datos (productos AR18-*). Si algo no cuadra
--    se detiene con un error "Unknown column 'ERROR: …'" que dice qué.
--  · Todo va en una transacción que solo se confirma al final: si una
--    sentencia falla, el COMMIT no llega y no queda nada a medias.
-- ============================================================

SET NAMES utf8mb4;

-- ── Validación previa ──
SET @personal := (SELECT COALESCE(
    (SELECT assigned_personal_id FROM cash_registers WHERE id = 15),
    (SELECT id FROM personals WHERE company_id = 18 AND user_id = 17 AND deleted_at IS NULL LIMIT 1)));

-- Diagnóstico: qué hay realmente en la base para estos IDs.
SELECT
    (SELECT COUNT(*) FROM companies WHERE id = 18 AND deleted_at IS NULL)       AS empresa_existe,
    (SELECT company_id   FROM branches WHERE id = 14)                         AS sucursal_empresa,
    (SELECT warehouse_id FROM branches WHERE id = 14)                         AS sucursal_almacen,
    (SELECT company_id   FROM cash_registers WHERE id = 15)                  AS caja_empresa,
    (SELECT assigned_personal_id FROM cash_registers WHERE id = 15)          AS caja_cajero,
    @personal                                                                  AS cajero_usado,
    (SELECT COUNT(*) FROM products WHERE company_id = 18 AND sku LIKE 'AR18-%') AS demo_ya_cargado;

SET @err := CASE
    WHEN (SELECT COUNT(*) FROM companies WHERE id = 18 AND deleted_at IS NULL) = 0 THEN 'ERROR: no existe la empresa 18'
    WHEN (SELECT COUNT(*) FROM users WHERE id = 17) = 0 THEN 'ERROR: no existe el usuario 17'
    WHEN (SELECT COUNT(*) FROM branches WHERE id = 14 AND company_id = 18 AND warehouse_id = 16) = 0 THEN 'ERROR: la sucursal 14 no es de la empresa 18 o su almacen no es el 16'
    WHEN (SELECT COUNT(*) FROM cash_registers WHERE id = 15 AND company_id = 18) = 0 THEN 'ERROR: la caja 15 no es de la empresa 18'
    WHEN @personal IS NULL THEN 'ERROR: la caja 15 no tiene cajero asignado'
    WHEN (SELECT COUNT(*) FROM products WHERE company_id = 18 AND sku LIKE 'AR18-%') > 0 THEN 'ERROR: los datos demo ya estaban cargados, no se hizo nada'
    ELSE NULL END;
SET @sql := IF(@err IS NULL, 'SELECT ''Validacion OK, cargando datos demo'' AS info', CONCAT('SELECT `', @err, '`'));
PREPARE stmt FROM @sql; EXECUTE stmt; DEALLOCATE PREPARE stmt;

