  -- ── Stock actual = suma de movimientos del almacén ──
  UPDATE products p
     SET current_stock = (SELECT COALESCE(SUM(CASE m.type WHEN 'in' THEN m.quantity WHEN 'out' THEN -m.quantity ELSE 0 END), 0)
                            FROM inventory_movements m
                           WHERE m.product_id = p.id AND m.warehouse_id = 16 AND m.deleted_at IS NULL)
   WHERE p.company_id = 18 AND p.sku LIKE 'AR18-%';

  -- ── Costo guardado en la venta (solo si ya existe sale_items.unit_cost) ──
  SET @sql := IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'sale_items' AND COLUMN_NAME = 'unit_cost') > 0,
      'UPDATE sale_items si JOIN sales s ON s.id = si.sale_id JOIN products p ON p.id = si.product_id SET si.unit_cost = p.cost WHERE s.company_id = 18 AND p.sku LIKE ''AR18-%'' AND si.unit_cost IS NULL',
